 [Serializable]public sealed class FileProof {public string Path,Sha256;}
 [Serializable]public sealed class ArchiveRow {public string source,archive,sha256;public bool verified;}
 [Serializable]public sealed class ArchiveRows {public ArchiveRow[] rows;}
 [Serializable]public sealed class CheckpointProof {public string Batch,SourceDirectory,RunId,ContentVersion,FinalRootPath,FinalRootSha256,ReportPath,ReportSha256,BatchManifestPath,BatchManifestSha256;public FileProof[] Files;}
 private static string Hash(string p){using(var sha=SHA256.Create())using(var stream=File.OpenRead(p))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");}
 private static string CloneCheckpoint(string proofPath,string destination,out CheckpointProof proof){
  proof=JsonUtility.FromJson<CheckpointProof>(File.ReadAllText(proofPath));Assert.That(proof.Batch,Is.Not.Null.And.Not.Empty);Assert.That(proof.RunId,Is.Not.Null.And.Not.Empty);
  Assert.That(Hash(proof.BatchManifestPath),Is.EqualTo(proof.BatchManifestSha256));
  Assert.That(new DirectoryInfo(Path.GetDirectoryName(proof.BatchManifestPath)).Name,Is.EqualTo(proof.Batch));
  var archive=JsonUtility.FromJson<ArchiveRows>("{\"rows\":"+File.ReadAllText(proof.BatchManifestPath)+"}").rows;
  foreach(var pair in new[]{new[]{proof.ReportPath,proof.ReportSha256},new[]{proof.FinalRootPath,proof.FinalRootSha256}})Assert.That(archive.Any(r=>r.verified&&r.sha256==pair[1]&&(Path.GetFullPath(r.archive)==Path.GetFullPath(pair[0])||Path.GetFullPath(r.source)==Path.GetFullPath(pair[0]))),Is.True,"Source evidence must belong to declared verified archive batch");
  Assert.That(Hash(proof.FinalRootPath),Is.EqualTo(proof.FinalRootSha256));Assert.That(Hash(proof.ReportPath),Is.EqualTo(proof.ReportSha256));
  Assert.That(File.ReadAllLines(proof.ReportPath).Contains("outcome=D8PreflightReached"),Is.True,"Source batch must be a sealed natural D8 preflight");
  string root=Path.GetFullPath(proof.SourceDirectory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
  var actual=Directory.GetFiles(root,"*",SearchOption.AllDirectories).Select(p=>p.Substring(root.Length).Replace('\\','/')).OrderBy(p=>p).ToArray();Assert.That(proof.Files.Select(f=>f.Path).OrderBy(p=>p).ToArray(),Is.EqualTo(actual),"Proof must list entire sealed save");Directory.CreateDirectory(destination);
  foreach(var f in proof.Files){string source=Path.GetFullPath(Path.Combine(root,f.Path));Assert.That(source.StartsWith(root,StringComparison.OrdinalIgnoreCase),Is.True);Assert.That(Hash(source),Is.EqualTo(f.Sha256));string output=Path.Combine(destination,f.Path);Directory.CreateDirectory(Path.GetDirectoryName(output));File.Copy(source,output,false);Assert.That(Hash(output),Is.EqualTo(f.Sha256));}
  return Hash(proofPath);
 }
 private static T Read<T>(GameSession s,string owner)=>JsonUtility.FromJson<T>(s.InspectSnapshot().FindFragment(owner,"player").Json);
 private static string HistoryJson(AchievementHistoryEntry h)=>JsonUtility.ToJson(h.Snapshot)+"\n"+h.NoteState+"\n"+h.Note;
 private static string PermanentJson(GameSession s)=>s.InspectSnapshot().PermanentFragments.Single(f=>f.Owner=="progression"&&f.Scope=="permanent").Json;
 [Serializable] private sealed class WorldStamp { public int Day;public string Phase,BarrierId; }
 private static RootEnvelope ObserveFreeze(GameSession s,RootEnvelope ready,ref bool verified){
  var root=s.InspectSnapshot();if(root==null)return ready;var sf=root.FindFragment("session","player");if(sf==null)return ready;
  var state=JsonUtility.FromJson<SessionState>(sf.Json);if(state.Day!=42)return ready;
  var c=JsonUtility.FromJson<CompetitionState>(root.FindFragment("competition","player").Json);
  Assert.That(c.Current.Ordinal,Is.EqualTo(1));Assert.That(c.Current.ContestDay,Is.EqualTo(42));
  var wf=root.FindFragment("world","shared");var world=wf==null?null:JsonUtility.FromJson<WorldStamp>(wf.Json);
  if(c.Current.FrozenActors.Length==0&&world!=null&&world.Day==42&&world.Phase=="DayOpenReady"){
   foreach(string actor in new[]{"player","rival","beginner","veteran","coach"}){var actorState=JsonUtility.FromJson<SessionState>(root.FindFragment("session",actor).Json);Assert.That(actorState.Day,Is.EqualTo(42));Assert.That(actorState.Phase,Is.EqualTo("DayOpenReady"));}
   return JsonUtility.FromJson<RootEnvelope>(JsonUtility.ToJson(root));
  }
  if(!verified&&c.Current.FrozenActors.Length>0){Assert.That(ready,Is.Not.Null,"Missing observed pre-freeze committed barrier");Assert.That(c.Current.BarrierId,Is.EqualTo(JsonUtility.FromJson<WorldStamp>(ready.FindFragment("world","shared").Json).BarrierId));Assert.That(c.Current.FrozenActors.Select(x=>x.ActorId).OrderBy(x=>x).ToArray(),Is.EqualTo(new[]{"player","rival"}));foreach(var actor in c.Current.FrozenActors){var body=JsonUtility.FromJson<FitnessSimulator.Game.Body.BodyState>(ready.FindFragment("body",actor.ActorId).Json);Assert.That(actor.Day,Is.EqualTo(42));Assert.That(actor.Phase,Is.EqualTo("DayOpenReady"));Assert.That(actor.SourceCommitId,Is.EqualTo(ready.LastCommitId));Assert.That(actor.ActorRevision,Is.EqualTo(body.Revision));Assert.That(actor.SourceKind,Is.EqualTo(actor.ActorId=="player"?CompetitionSourceKind.PlayerProduction:CompetitionSourceKind.NpcProduction));Assert.That(root.FindFragment("body",actor.ActorId).Json,Is.EqualTo(ready.FindFragment("body",actor.ActorId).Json));Assert.That(JsonUtility.ToJson(actor.Body),Is.EqualTo(JsonUtility.ToJson(body)));}verified=true;}
  return ready;
 }
 private sealed class Driver:IDisposable {
  public GameSession S;public readonly string DirectoryPath,Save;public readonly Stopwatch Watch=Stopwatch.StartNew();public readonly int Seconds;
  public string Variant="dual-original-v1",LastReplyMessage="";public int Commands,Inputs,Clocks,Steps;public int Day=8;public bool NeedsRest;public string Outcome="BudgetExhausted",Error="";
  private readonly string prefix="dual/"+Guid.NewGuid().ToString("N")+"/";private readonly StreamWriter writer;private readonly System.Collections.Generic.HashSet<string> views=new System.Collections.Generic.HashSet<string>();
  public Driver(string dir,int seconds){DirectoryPath=dir;Save=Path.Combine(dir,"save");Seconds=seconds;S=GameSession.OpenAutomation(Save,1);writer=new StreamWriter(Path.Combine(dir,"trace.jsonl"));}
  public void Log(string line){if(Watch.Elapsed.TotalSeconds>Seconds)throw new InvalidOperationException("WallBudgetExceeded");if(writer.BaseStream.Position>268435456)throw new InvalidOperationException("EvidenceBudgetExceeded");if(line.StartsWith("advance-ms="))Clocks++;if(line.Contains("\"ActionId\":\"training-input\""))Inputs++;if(line.StartsWith("{\"RunId\":")&&line.Contains("\"ScreenId\":")){string hash=ContentHash.Sha256(line);line=views.Add(hash)?"{\"viewHash\":\""+hash+"\",\"view\":"+line+"}":"{\"viewRef\":\""+hash+"\"}";}writer.WriteLine(line);}
  public FrontendView View(){if(++Steps>500000)throw new InvalidOperationException("OuterStepBudgetExceeded");var v=S.ReadView();Log(JsonUtility.ToJson(v));Assert.That(v.ScreenId,Is.Not.EqualTo("error"),v.Body);var m=System.Text.RegularExpressions.Regex.Match(v.Status??"",@"第\s*(\d+)\s*日");if(m.Success)Day=int.Parse(m.Groups[1].Value);Assert.That(Day,Is.LessThanOrEqualTo(43));if(v.ScreenId.StartsWith("summary/"))NeedsRest=false;return v;}
  public void Send(FrontendOption o){var v=S.ReadView();var a=new FrontendAction{RunId=v.RunId,ExpectedRevision=v.Revision,OperationId=prefix+(++Commands),ActionId=o.Id,StringValue=o.StringValue,IntValue=o.IntValue};Log(JsonUtility.ToJson(v));Log(JsonUtility.ToJson(a));var r=S.Execute(a);LastReplyMessage=r.Message;Log(JsonUtility.ToJson(r));Assert.That(r.Accepted,Is.True,r.Message);if(o.Id=="settle")NeedsRest=true;if(o.Id=="competition-enroll"||o.Id=="competition-attend"||o.Id=="competition-decline"||o.Id=="ending-continue"||o.Id=="ending-empty"){string root=JsonUtility.ToJson(S.InspectSnapshot());Assert.That(S.Execute(a).Accepted,Is.True);Assert.That(JsonUtility.ToJson(S.InspectSnapshot()),Is.EqualTo(root));}}
  public bool Normal(FrontendView v,bool bodybuilding){var options=v.Actions.Where(a=>a.Enabled).ToArray();FrontendOption o=null;
   if(v.TrainingInput!=null){Assert.That(PublicEightInputDriver.DriveActiveSet(S,v.TrainingInput.ExerciseId,Log),Is.EqualTo("AwaitProductionResult"));return true;}
   if(options.Any(a=>a.Id=="begin-set")){if(NeedsRest){o=options.First(a=>a.Id=="rest"&&a.IntValue==180);Send(o);NeedsRest=false;return true;}bool first=System.Text.RegularExpressions.Regex.IsMatch(v.Body??"",@"第\s*1\s*组");o=bodybuilding&&first?options.FirstOrDefault(a=>a.Id=="begin-set"&&a.IntValue==1):null;o=o??options.FirstOrDefault(a=>a.Id=="begin-set"&&a.StringValue=="auto")??options.First(a=>a.Id=="begin-set"&&a.StringValue=="manual"&&a.IntValue==0);}
   if(o==null&&options.Any(a=>a.Id=="choose-entry"))o=options.FirstOrDefault(a=>a.Id=="choose-entry"&&a.StringValue=="training-choice")??options.First(a=>a.Id=="choose-entry");
   if(o==null&&options.Any(a=>a.Id=="meal")){o=options.FirstOrDefault(a=>a.Id=="meal"&&new[]{"porridge_egg","home_rice","home_noodles"}.Contains(a.StringValue));Assert.That(o,Is.Not.Null,"CoverageMissing: paid meal unavailable");}
   foreach(var id in new[]{"continue-game","ending-segment","ending-empty","settle","continue","shop-leave","item-use","competition-next","next-day"})if(o==null)o=options.FirstOrDefault(a=>a.Id==id);
   if(o!=null){Send(o);return true;}var unknown=options.FirstOrDefault(a=>!new[]{"save-plan","open-menu","competition-menu","history-open","new-game"}.Contains(a.Id));Assert.That(unknown,Is.Null,"MissingHandler: "+v.ScreenId+"/"+unknown?.Id);Log("advance-ms=0");S.Advance(0);return true;
  }
  public System.Collections.Generic.List<AchievementHistoryEntry> History(){string root=JsonUtility.ToJson(S.InspectSnapshot());S.Dispose();System.Collections.Generic.List<AchievementHistoryEntry> entries;using(var store=new LocalCheckpointStore(Save,new UnityJsonStateCodec())){store.Load();entries=new EndingProgression(new UnityJsonStateCodec()).ReadHistory(store,0,64);}S=GameSession.OpenAutomation(Save,1);Assert.That(JsonUtility.ToJson(S.InspectSnapshot()),Is.EqualTo(root));return entries;}
  public void Dispose(){writer.Flush();File.WriteAllText(Path.Combine(DirectoryPath,"final.json"),JsonUtility.ToJson(S.InspectSnapshot(),true));File.WriteAllText(Path.Combine(DirectoryPath,"report.txt"),"variant="+Variant+"\noutcome="+Outcome+"\nexception="+Error+"\nmaxSeconds="+Seconds+"\nelapsedSeconds="+Watch.Elapsed.TotalSeconds+"\nmaxDay=43\nmaxSteps=500000\nsteps="+Steps+"\nbusinessCommands="+Commands+"\ninputEdges="+Inputs+"\nclockCalls="+Clocks+"\nevidenceByteLimit=268435456\nevidenceBytes="+writer.BaseStream.Length);S.Dispose();writer.Dispose();}
 }
 private static void CopySave(string source,string destination){Assert.That(Directory.Exists(destination),Is.False);Directory.CreateDirectory(destination);var root=Path.GetFullPath(source).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;var rows=new System.Collections.Generic.List<FileProof>();foreach(string file in Directory.GetFiles(root,"*",SearchOption.AllDirectories)){string relative=file.Substring(root.Length);string target=Path.Combine(destination,relative);Directory.CreateDirectory(Path.GetDirectoryName(target));string hash=Hash(file);File.Copy(file,target);Assert.That(Hash(target),Is.EqualTo(hash));Assert.That(Hash(file),Is.EqualTo(hash));rows.Add(new FileProof{Path=relative.Replace('\\','/'),Sha256=hash});}File.WriteAllText(Path.Combine(Path.GetDirectoryName(destination),"checkpoint-files.json"),JsonUtility.ToJson(new CheckpointProof{SourceDirectory=root,Files=rows.ToArray()},true));}
 [TestCase(true),TestCase(false),Explicit("Requires sealed D8 proof and explicit finite budgets"),Timeout(7260000)]
 public void NaturalD8DualRegistrationBranches(bool bodybuilding)=>RunD8Candidate(bodybuilding,false);
 [Test,Explicit("Only after baseline MorningChampionAfternoonLoss CoverageMissing"),Timeout(7260000)]
 public void NaturalD8SaturdayCurlChampionThenLoss()=>RunD8Candidate(true,true);
 private static void SaveSaturdayCurl(Driver d,FrontendView view,FrontendOption option){
  Assert.That(d.Day,Is.EqualTo(8),"Variant must be registered on original D8");var draft=JsonUtility.FromJson<PlanDraft>(option.StringValue);Assert.That(draft.Mode,Is.EqualTo(PlanMode.NaturalWeek));Assert.That(draft.Slots.Length,Is.EqualTo(7));
  var unchanged=draft.Slots.Where(x=>x.Index!=5).ToDictionary(x=>x.Index,x=>JsonUtility.ToJson(x));var saturday=draft.Slots.Single(x=>x.Index==5);Assert.That(saturday.IsRest,Is.False);Assert.That(saturday.Volume,Is.EqualTo(TrainingVolume.High));Assert.That(saturday.Combination,Is.EqualTo(TrainingCombination.Shoulders));Assert.That(saturday.AnchorId,Is.EqualTo("afternoon"));Assert.That(saturday.Entries.Select(x=>x.ExerciseId).ToArray(),Is.EqualTo(new[]{"shoulder_press","lateral_raise"}));
  saturday.Combination=TrainingCombination.Free;saturday.Entries=saturday.Entries.Concat(new[]{new PlanEntryDraft{EntryId="slot-5-extra-curl-v1",ExerciseId="dumbbell_curl"}}).ToArray();foreach(var slot in draft.Slots.Where(x=>x.Index!=5))Assert.That(JsonUtility.ToJson(slot),Is.EqualTo(unchanged[slot.Index]));
  var publiclyAvailable=view.PlanAnchorOptions.Where(x=>x.Enabled).Select(x=>x.Id).ToArray();var issues=PlanRules.Validate(draft,d.Day+1,new AnchorEligibility(d.Day,Array.Empty<string>(),publiclyAvailable),new TrainingCatalogAdapter());Assert.That(issues,Is.Empty,string.Join("; ",issues));
  string activeBefore=JsonUtility.ToJson(Read<PlanStateRecord>(d.S,"plan").Active);d.Send(new FrontendOption{Id=option.Id,StringValue=JsonUtility.ToJson(draft),IntValue=option.IntValue});Assert.That(d.LastReplyMessage,Does.Contain("明日起生效"));var committed=Read<PlanStateRecord>(d.S,"plan");Assert.That(committed.HasPending,Is.True);Assert.That(committed.Pending.EffectiveDay,Is.EqualTo(9));Assert.That(JsonUtility.ToJson(committed.Active),Is.EqualTo(activeBefore));Assert.That(JsonUtility.ToJson(committed.Pending.Draft),Is.EqualTo(JsonUtility.ToJson(draft)));
 }
 private void RunD8Candidate(bool bodybuilding,bool saturdayCurl){
  string variant=saturdayCurl?"dual-saturday-high-free-curl-v1":"dual-original-v1";string prerequisiteReport=null;
  if(saturdayCurl){prerequisiteReport=Environment.GetEnvironmentVariable("FITNESS_DUAL_BASELINE_BRANCH_REPORT");Assert.That(File.Exists(prerequisiteReport),Is.True,"Baseline actual branch report required");Assert.That(new DirectoryInfo(Path.GetDirectoryName(prerequisiteReport)).Name,Is.EqualTo("MorningChampionAfternoonLoss"));Assert.That(File.ReadAllLines(prerequisiteReport).Contains("outcome=CoverageMissing"),Is.True,"Variant is gated on real baseline target miss");}

  string proofPath=Environment.GetEnvironmentVariable(bodybuilding?"FITNESS_DUAL_BODY_PROOF":"FITNESS_DUAL_THIN_PROOF");Assert.That(File.Exists(proofPath),Is.True,"Sealed natural D8 source required");
  int prepareSeconds=int.Parse(Environment.GetEnvironmentVariable("FITNESS_DUAL_PREPARE_SECONDS")??throw new InvalidOperationException("Explicit prepare budget required"));int branchSeconds=int.Parse(Environment.GetEnvironmentVariable("FITNESS_DUAL_BRANCH_SECONDS")??throw new InvalidOperationException("Explicit branch budget required"));Assert.That(prepareSeconds,Is.InRange(1,6000));Assert.That(branchSeconds,Is.InRange(1,600));Assert.That(prepareSeconds+2*branchSeconds,Is.LessThanOrEqualTo(7200));
  string run=Path.Combine(Path.GetTempPath(),"Fitness-Dual-Contest",Guid.NewGuid().ToString("N")),prepare=Path.Combine(run,"prepare");Directory.CreateDirectory(prepare);CheckpointProof proof;string proofHash=CloneCheckpoint(proofPath,Path.Combine(prepare,"save"),out proof);File.Copy(proofPath,Path.Combine(run,"source-proof.json"));Assert.That(File.ReadAllLines(proof.ReportPath).Contains("contest="+(bodybuilding?"Bodybuilding":"ThinBuild")),Is.True);File.WriteAllText(Path.Combine(run,"source-binding.txt"),"variant="+variant+"\nvariantPrerequisiteReportSha256="+(prerequisiteReport==null?"":Hash(prerequisiteReport))+"\nbatch="+proof.Batch+"\nproofSha256="+proofHash+"\nsourceRunId="+proof.RunId+"\ncurrentGameAssemblySha256="+Hash(typeof(GameSession).Assembly.Location)+"\ncurrentTestAssemblySha256="+Hash(typeof(DualContestBranchTests).Assembly.Location));
  if(saturdayCurl){var prerequisiteProof=JsonUtility.FromJson<CheckpointProof>(File.ReadAllText(Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(prerequisiteReport)),"source-proof.json")));Assert.That(prerequisiteProof.RunId,Is.EqualTo(proof.RunId));Assert.That(prerequisiteProof.FinalRootSha256,Is.EqualTo(proof.FinalRootSha256));}
  bool variantSaved=!saturdayCurl;
  string checkpointRoot=null;bool ready=false,dual=false,freezeVerified=false;RootEnvelope freezeReady=null;
  using(var d=new Driver(prepare,prepareSeconds)){try{d.Variant=variant;
   Assert.That(JsonUtility.ToJson(d.S.InspectSnapshot()),Is.EqualTo(JsonUtility.ToJson(JsonUtility.FromJson<RootEnvelope>(File.ReadAllText(proof.FinalRootPath)))));Assert.That(Read<SessionState>(d.S,"session").Day,Is.EqualTo(8));Assert.That(d.S.InspectSnapshot().RunId,Is.EqualTo(proof.RunId));var initial=Read<CompetitionState>(d.S,"competition").Current;Assert.That(initial.Ordinal,Is.EqualTo(1));Assert.That(initial.Contest(bodybuilding?ContestKind.Bodybuilding:ContestKind.ThinBuild).Enrolled,Is.True);Assert.That(initial.Contest(bodybuilding?ContestKind.ThinBuild:ContestKind.Bodybuilding).Enrolled,Is.False);
   for(;;){freezeReady=ObserveFreeze(d.S,freezeReady,ref freezeVerified);var v=d.View();var options=v.Actions.Where(a=>a.Enabled).ToArray();
    if(!variantSaved){var edit=options.FirstOrDefault(a=>a.Id=="save-plan");if(edit!=null){SaveSaturdayCurl(d,v,edit);variantSaved=true;continue;}}
    if(options.Any(a=>a.Id=="competition-attend"&&a.IntValue==0)){Assert.That(dual&&freezeVerified&&variantSaved,Is.True);var edition=Read<CompetitionState>(d.S,"competition").Current;Assert.That(edition.Contests.All(c=>c.Enrolled&&!c.WindowClosed&&c.Results.Length==0),Is.True);Assert.That(edition.ActualAttendanceCount,Is.Zero);checkpointRoot=JsonUtility.ToJson(d.S.InspectSnapshot());ready=true;d.Outcome="DualD42CheckpointReady";break;}
    if(!dual&&options.Any(a=>a.Id=="competition-menu")){d.Send(options.First(a=>a.Id=="competition-menu"));continue;}
    if(v.ScreenId=="competition"){var enroll=options.FirstOrDefault(a=>a.Id=="competition-enroll"&&a.IntValue==(bodybuilding?1:0));if(!dual&&enroll!=null){d.Send(enroll);Assert.That(Read<CompetitionState>(d.S,"competition").Current.Contests.All(c=>c.Enrolled),Is.True);dual=true;continue;}var close=options.FirstOrDefault(a=>a.Id=="competition-close");if(close!=null){d.Send(close);continue;}}
    if(v.ScreenId=="ending-menu")throw new InvalidOperationException("CoverageMissing: terminal before D42 checkpoint");d.Normal(v,bodybuilding);
   }
  }catch(Exception e){d.Error=e.ToString();d.Outcome=e.Message.Contains("CoverageMissing")?"CoverageMissing":"AssertionOrBudgetFailure";throw;}}
  Assert.That(ready,Is.True);File.WriteAllText(Path.Combine(run,"checkpoint-root.json"),checkpointRoot);var failures=new System.Collections.Generic.List<string>();
  foreach(string branch in saturdayCurl?new[]{"MorningChampionAfternoonLoss"}:bodybuilding?new[]{"MorningChampionAfternoonDecline","MorningChampionAfternoonLoss"}:new[]{"MorningDeclineAfternoonChampion"}){string destination=Path.Combine(run,branch);Directory.CreateDirectory(destination);CopySave(Path.Combine(prepare,"save"),Path.Combine(destination,"save"));try{RunBranch(destination,checkpointRoot,branch,branchSeconds,variant);}catch(Exception e){failures.Add(branch+": "+e.Message);}}
  File.WriteAllText(Path.Combine(run,"branches.txt"),failures.Count==0?"AllRequestedBranchesVerified":string.Join("\n",failures));TestContext.WriteLine(run);Assert.That(failures,Is.Empty,string.Join("\n",failures));
 }
 private static void RunBranch(string dir,string checkpointRoot,string branch,int seconds,string variant="dual-original-v1"){
  using(var d=new Driver(dir,seconds)){try{d.Variant=variant;Assert.That(JsonUtility.ToJson(d.S.InspectSnapshot()),Is.EqualTo(checkpointRoot));bool morningDecline=branch=="MorningDeclineAfternoonChampion",afternoonLoss=branch=="MorningChampionAfternoonLoss";bool morningDone=false,afternoonDone=false,targetReached=false;string successEnding=morningDecline?"lean_champion":"bodybuilding_champion",successId=null,successRecord=null;var old=d.History().ToDictionary(h=>h.Snapshot.AchievementId,HistoryJson);d.Day=42;
   for(;;){var v=d.View();var options=v.Actions.Where(a=>a.Enabled).ToArray();
    if(d.Day==43&&Read<CompetitionState>(d.S,"competition").Current.Ordinal==2){Assert.That(afternoonLoss,Is.False,"CoverageMissing: afternoon did not lose");Assert.That(morningDone&&afternoonDone&&successRecord!=null,Is.True,"CoverageMissing: target combination not reached");targetReached=true;break;}
    if(v.ScreenId=="ending-menu"&&!options.Any(a=>a.Id=="ending-continue")){var pr=Read<ProgressionRun>(d.S,"progression");Assert.That(pr.TerminalLock,Is.True);if(!afternoonLoss||!morningDone||!afternoonDone||successRecord==null)throw new InvalidOperationException("CoverageMissing: actual terminal before requested combination");Assert.That(pr.Active.EndingId,Is.EqualTo("competition_failed"));Assert.That(pr.Active.NoteState,Is.EqualTo(AchievementNoteState.CommittedEmpty));targetReached=true;break;}
    var resume=options.FirstOrDefault(a=>a.Id=="ending-continue");if(resume!=null){var pr=Read<ProgressionRun>(d.S,"progression");if(pr.Active.EndingId!=successEnding)throw new InvalidOperationException("CoverageMissing: actual successful ending differs from requested branch");successId=pr.Active.AchievementId;if(morningDone&&!afternoonDone)Assert.That(Read<CompetitionState>(d.S,"competition").Current.Contest(ContestKind.ThinBuild).Results,Is.Empty,"Afternoon must remain unscored before morning success continuation");var normal=d.S.InspectSnapshot().Fragments.Where(f=>f.Owner!="progression").ToDictionary(f=>f.Owner.Length+":"+f.Owner+f.Scope,JsonUtility.ToJson);d.Send(resume);if(morningDone&&!afternoonDone)Assert.That(Read<CompetitionState>(d.S,"competition").Current.Contest(ContestKind.ThinBuild).Results,Is.Empty,"Afternoon must remain unscored after morning success continuation");foreach(var f in d.S.InspectSnapshot().Fragments.Where(f=>f.Owner!="progression"))Assert.That(JsonUtility.ToJson(f),Is.EqualTo(normal[f.Owner.Length+":"+f.Owner+f.Scope]));var entry=d.History().Single(h=>h.Snapshot.AchievementId==successId);successRecord=HistoryJson(entry);continue;}
    if(v.ScreenId=="competition"){
     int kind=morningDone?1:0;bool decline=kind==0?morningDecline:!morningDecline&&!afternoonLoss;var action=options.FirstOrDefault(a=>a.IntValue==kind&&a.Id==(decline?"competition-decline":"competition-attend"));
     if(action!=null){d.Send(action);var c=Read<CompetitionState>(d.S,"competition");var contest=c.Current.Contest((ContestKind)kind);if(kind==0)Assert.That(c.Current.Contest(ContestKind.ThinBuild).Results,Is.Empty,"Afternoon must remain unscored after morning submission");if(decline){Assert.That(contest.Declined,Is.True);Assert.That(contest.Results,Is.Empty);}else{NaturalChampionRouteTests.AuditScores(d.S,(ContestKind)kind,false);bool won=contest.Results.Single().Score.Participants.Single(p=>p.ActorId==c.PlayerId).Rank==1;bool expectWin=kind==0||morningDecline;if(won!=expectWin){d.Outcome="CoverageMissing: "+branch+" actual "+kind+" rank="+(won?1:2);throw new InvalidOperationException(d.Outcome);}}if(kind==0)morningDone=true;else afternoonDone=true;continue;}
     var close=options.FirstOrDefault(a=>a.Id=="competition-close");if(close!=null){d.Send(close);continue;}
    }
    d.Normal(v,!morningDecline);
   }
   Assert.That(targetReached,Is.True);var finalCompetition=Read<CompetitionState>(d.S,"competition");var e=finalCompetition.Editions.Single(x=>x.Ordinal==1);Assert.That(e.ActualAttendanceCount,Is.EqualTo(afternoonLoss?2:1));Assert.That(e.Facts.Count(f=>f.Kind==CompetitionFactKind.Champion),Is.EqualTo(1));Assert.That(e.Facts.Count(f=>f.Kind==CompetitionFactKind.NonChampion),Is.EqualTo(afternoonLoss?1:0));var history=d.History();foreach(var pair in old)Assert.That(HistoryJson(history.Single(h=>h.Snapshot.AchievementId==pair.Key)),Is.EqualTo(pair.Value));Assert.That(HistoryJson(history.Single(h=>h.Snapshot.AchievementId==successId)),Is.EqualTo(successRecord));Assert.That(history.Count(h=>h.Snapshot.RunId==d.S.InspectSnapshot().RunId&&h.Snapshot.EndingId==successEnding),Is.EqualTo(1));Assert.That(history.Count(h=>h.Snapshot.RunId==d.S.InspectSnapshot().RunId&&h.Snapshot.EndingId=="competition_failed"),Is.EqualTo(afternoonLoss?1:0));var grants=JsonUtility.FromJson<ProgressionPermanent>(PermanentJson(d.S));Assert.That(grants.TemplateGrants.Count(g=>g.TemplateId==(morningDecline?"lean_social":"strength_foundation")),Is.EqualTo(1));Assert.That(grants.TemplateGrants.Single(g=>g.TemplateId==(morningDecline?"lean_social":"strength_foundation")).AchievementId,Is.EqualTo(successId));if(afternoonLoss){Assert.That(Read<ProgressionRun>(d.S,"progression").TerminalLock,Is.True);Assert.That(d.S.ReadView().Actions.Any(a=>a.Enabled&&a.Id=="ending-continue"),Is.False);}d.Outcome=branch+"Verified";
  }catch(Exception ex){d.Error=ex.ToString();if(ex.Message.Contains("CoverageMissing"))d.Outcome="CoverageMissing";else d.Outcome="AssertionOrBudgetFailure";throw;}}
 }
